use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::Error;
use crate::settings::AttributePatch;

/// Characters allowed in queue names, group ids and deduplication ids.
pub fn is_token_char(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'-'
}

pub fn opt_string<'v>(name: &str, value: Option<&'v Value>) -> Result<Option<&'v str>, Error> {
    match value {
        None => Ok(None),
        Some(Value::String(s)) => Ok(Some(s)),
        Some(_) => Err(Error::invalid_value(name, "must be a string")),
    }
}

pub fn opt_bool(name: &str, value: Option<&Value>) -> Result<Option<bool>, Error> {
    match value {
        None => Ok(None),
        Some(Value::Bool(b)) => Ok(Some(*b)),
        Some(_) => Err(Error::invalid_value(name, "must be a boolean")),
    }
}

/// Accepts only JSON numbers written as integers (`30`, not `30.0` or `3e1`).
pub fn opt_integer(
    name: &str,
    value: Option<&Value>,
    range: RangeInclusive<u32>,
) -> Result<Option<u32>, Error> {
    let Some(value) = value else { return Ok(None) };
    let parsed = match value {
        Value::Number(n) if !n.is_f64() => n.as_i64(),
        _ => None,
    };
    parsed
        .and_then(|n| u32::try_from(n).ok())
        .filter(|n| range.contains(n))
        .map(Some)
        .ok_or_else(|| {
            Error::invalid_value(
                name,
                &format!(
                    "must be an integer from {} to {}",
                    range.start(),
                    range.end()
                ),
            )
        })
}

/// The members of one command object; `null` members count as absent.
pub struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    pub fn new(members: &'a Map<String, Value>) -> Self {
        Self(members)
    }

    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|v| !v.is_null())
    }

    /// Fails with `MissingParameter` for the first absent name.
    pub fn require(&self, names: &[&str]) -> Result<(), Error> {
        match names.iter().find(|name| self.get(name).is_none()) {
            Some(name) => Err(Error::missing(name)),
            None => Ok(()),
        }
    }

    pub fn string(&self, name: &str) -> Result<Option<&'a str>, Error> {
        opt_string(name, self.get(name))
    }

    pub fn required_string(&self, name: &str) -> Result<&'a str, Error> {
        self.string(name)?.ok_or_else(|| Error::missing(name))
    }

    /// A group or deduplication id: 1 to 128 token characters.
    pub fn identifier(&self, name: &str) -> Result<Option<&'a str>, Error> {
        let id = self.string(name)?;
        match id {
            Some(s) if !(1..=128).contains(&s.len()) || !s.bytes().all(is_token_char) => Err(
                Error::invalid_value(name, "must be 1 to 128 characters from A-Z a-z 0-9 _ -"),
            ),
            _ => Ok(id),
        }
    }

    pub fn integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<Option<u32>, Error> {
        opt_integer(name, self.get(name), range)
    }

    pub fn required_integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<u32, Error> {
        self.integer(name, range)?
            .ok_or_else(|| Error::missing(name))
    }

    pub fn attributes(&self, name: &str) -> Result<Option<AttributePatch>, Error> {
        match self.get(name) {
            None => Ok(None),
            Some(Value::Object(members)) => AttributePatch::parse(members).map(Some),
            Some(_) => Err(Error::invalid_value(name, "must be an object")),
        }
    }
}
