use serde_json::{Map, Value};

use crate::error::Error;
use crate::params::{opt_bool, opt_integer, opt_string};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u32,
}

/// The attributes of a queue.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Settings {
    pub visibility_timeout: u32,
    pub delay_seconds: u32,
    pub retention_seconds: u32,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay_seconds: 0,
            retention_seconds: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

impl Settings {
    /// Overwrites the attributes present in `patch`. `dead_letter` is the
    /// patch's validated dead-letter pair, kept when `None`.
    pub fn apply(&mut self, patch: &AttributePatch, dead_letter: Option<DeadLetter>) {
        if let Some(v) = patch.visibility_timeout {
            self.visibility_timeout = v;
        }
        if let Some(v) = patch.delay_seconds {
            self.delay_seconds = v;
        }
        if let Some(v) = patch.retention_seconds {
            self.retention_seconds = v;
        }
        if let Some(v) = patch.fifo {
            self.fifo = v;
        }
        if let Some(v) = patch.content_based_deduplication {
            self.content_based_deduplication = v;
        }
        if dead_letter.is_some() {
            self.dead_letter = dead_letter;
        }
    }
}

/// The attributes named in a request, each type- and range-checked.
#[derive(Debug, Default)]
pub struct AttributePatch {
    pub visibility_timeout: Option<u32>,
    pub delay_seconds: Option<u32>,
    pub retention_seconds: Option<u32>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    dead_letter_queue: Option<String>,
    max_receive_count: Option<u32>,
}

impl AttributePatch {
    pub fn parse(members: &Map<String, Value>) -> Result<Self, Error> {
        let mut patch = Self::default();
        for (name, value) in members {
            let value = Some(value).filter(|v| !v.is_null());
            match name.as_str() {
                "VisibilityTimeout" => {
                    patch.visibility_timeout = opt_integer(name, value, 0..=43_200)?
                }
                "DelaySeconds" => patch.delay_seconds = opt_integer(name, value, 0..=900)?,
                "RetentionSeconds" => {
                    patch.retention_seconds = opt_integer(name, value, 60..=1_209_600)?
                }
                "Fifo" => patch.fifo = opt_bool(name, value)?,
                "ContentBasedDeduplication" => {
                    patch.content_based_deduplication = opt_bool(name, value)?
                }
                "DeadLetterQueue" => {
                    patch.dead_letter_queue = opt_string(name, value)?.map(str::to_owned)
                }
                "MaxReceiveCount" => patch.max_receive_count = opt_integer(name, value, 1..=1000)?,
                _ => return Err(Error::invalid_value(name, "unknown attribute")),
            }
        }
        Ok(patch)
    }

    /// The dead-letter configuration, which must be given as a pair or not at all.
    pub fn dead_letter(&self) -> Result<Option<DeadLetter>, Error> {
        match (&self.dead_letter_queue, self.max_receive_count) {
            (Some(queue), Some(max_receive_count)) => Ok(Some(DeadLetter {
                queue: queue.clone(),
                max_receive_count,
            })),
            (None, None) => Ok(None),
            _ => Err(Error::invalid_value(
                "Attributes",
                "DeadLetterQueue and MaxReceiveCount must be given together",
            )),
        }
    }
}
