        let position = self.in_flight_position(handle, now)?;
        self.messages.remove(position);
        Ok(())
    }

    pub fn change_visibility(
        &mut self,
        handle: ReceiptHandle,
        now: u64,
        timeout: u32,
    ) -> Result<(), Error> {
        let position = self.in_flight_position(handle, now)?;
        self.messages[position].hold = Hold::InFlight {
            until: now + u64::from(timeout),
            receipt: handle,
        };
        Ok(())
    }
}
